$('apply').onclick=()=>{if(!pending)return;try{const map={};for(const s of $('mapping').querySelectorAll('select'))if(s.value)map[s.dataset.joint]=s.value;puppet.setMotion(pending,map);clips();$('status').textContent='관절 연결 완료';}catch(e){$('status').textContent=e.message;}};
